using System;
using System.Collections;
using System.IO;
using System.Text;
using UnityEngine;
// Isolated, position-controlled lifecycle checks. Does not use a user's campaign file.
public sealed class PassengerBehaviorProbe:MonoBehaviour {
 DriveSession s;int checks,serial;readonly StringBuilder report=new StringBuilder();bool reload;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Attach(){var a=Environment.GetCommandLineArgs();if(Array.IndexOf(a,"-passengerBehaviorTest")>=0||Array.IndexOf(a,"-passengerBehaviorReloadTest")>=0)new GameObject("Passenger behavior probe").AddComponent<PassengerBehaviorProbe>();}
 void Check(bool ok,string why){checks++;report.AppendLine((ok?"PASS ":"FAIL ")+why);if(!ok)throw new Exception(why);}
 void Stop(int i){var p=s.jobs.stops[i];s.taxi.body.position=p.Kerb+Vector3.up*.65f;s.taxi.body.rotation=Quaternion.LookRotation(p.Direction);s.taxi.transform.SetPositionAndRotation(s.taxi.body.position,s.taxi.body.rotation);Physics.SyncTransforms();s.requests.AdvanceSafeStop(2.1f);}
 void FreezeSystems(){s.business.enabled=false;s.jobs.enabled=false;s.jobs.nav.enabled=false;s.requests.enabled=false;s.law.enabled=false;s.manners.enabled=false;s.GetComponent<ServiceLawZones>().enabled=false;s.taxi.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;foreach(var c in s.traffic.cars){c.Recycle();c.enabled=false;}}
 void Fresh(){s.business.settings=PrototypeSettings.ForThreeDays();s.business.ledger=new EconomyLedger(s.business.settings);s.business.passengers.Clear();s.business.enabledCampaign=s.business.useV2=true;s.business.preparing=false;s.paused=false;Time.timeScale=1;s.law.ids=new PrototypeIds("behavior-probe-"+(serial++));s.law.ledger=new LawLedger();s.law.tripId="";s.jobs.ClearForDay();s.jobs.ForcedRideCase=DrunkRideCase.Random;s.GetComponent<RideCompletionPanel>().Close();}
 void Begin(PassengerType type){s.jobs.ForcedPassengerType=type;string seed="probe-"+serial+"-"+type;var offer=new JobOffer{pickup=0,drop=3,fare=5000,seconds=300,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3]),candidateSeed=seed};s.jobs.offers[0]=offer;Stop(0);Check(s.jobs.Accept(0)&&s.jobs.Interact(),"begin "+type);s.requests.AdvanceSafeStop(2.1f);Check(s.jobs.Behavior!=null&&s.jobs.Behavior.Type==type,"actual type "+type);}
 // Synchronous position fixtures model a later input frame explicitly; the coroutine below also tests real frame boundaries.
 void NextInputFrame(){typeof(PassengerRequestUI).GetField("responseBlockedFrame",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(s.requests,Time.frameCount-1);}
 void Answer(int choice){NextInputFrame();if(s.requests.HasPendingChoice)s.requests.Choose(PassengerReply.Defer);NextInputFrame();s.requests.AdvanceSafeStop(2.1f);Check(s.jobs.RespondBehavior(choice),"answer "+s.jobs.Behavior.Type+"/"+choice);}
 PassengerJobsSnapshot RoundTrip(){var state=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(s.jobs.CaptureLive()));s.jobs.RestoreLive(state);s.requests.AdvanceSafeStop(2.1f);return state;}
 void Deliver(){Stop(s.jobs.current.drop);Check(s.jobs.Interact(),"first valid arrival");if(s.jobs.Active&&s.jobs.Behavior.WorkRemaining>0)s.jobs.AdvanceBehavior(10);if(s.jobs.Active&&s.jobs.DrunkRide.Waiting){s.jobs.DrunkRide.Advance(30,1);Check(s.jobs.Interact(),"wake after safe wait");}Check(!s.jobs.Active&&s.business.passengers.Count==1,"one completed passenger result");Check(s.business.passengers[0].request.Contains(s.jobs.Behavior.TypeLabel),"type and variant in detailed result");}
 void MainChecks(){
  Fresh();Begin(PassengerType.Luggage);Answer(0);s.jobs.AdvanceBehavior(9);int ordinal=s.business.ledger.Care.Snapshot().encounterOrdinal;s.business.ledger.RequestClose();s.jobs.AdvanceBehavior(1);Check(s.jobs.trip.State==TripState.ToPickup&&!s.jobs.Behavior.Boarded&&s.business.ledger.Care.Snapshot().encounterOrdinal==ordinal,"closing during last load second cannot board or consume encounter");
  Fresh();Begin(PassengerType.General);Stop(0);bool any=false;for(int i=1;i<Mathf.Min(12,s.jobs.stops.Length);i++){s.jobs.nav.SetDestination(s.jobs.stops[0]);int goal=s.jobs.nav.hdGoal;bool destination=s.jobs.nav.HasLargeRoadAlternativeTo(s.jobs.stops[i]);Check(s.jobs.nav.hdGoal==goal,"candidate query preserves pickup destination");s.jobs.nav.SetDestination(s.jobs.stops[i]);bool actual=s.jobs.nav.HasLargeRoadAlternative();Check(destination==actual,"candidate broad-road eligibility matches actual trip destination");any|=destination;}Check(any,"actual map offers a broad-road destination");

  Fresh();Begin(PassengerType.Luggage);Check(s.jobs.trip.State==TripState.ToPickup,"luggage preparation precedes actual boarding");float pickup=s.jobs.trip.PickupRemaining;Answer(0);Check(s.jobs.BehaviorWorkProtected,"required safe work protects deadline");s.jobs.AdvanceBehavior(4);Check(s.jobs.Behavior.PreparationRemaining==6&&s.jobs.trip.PickupRemaining==pickup,"partial load and pickup time protected");RoundTrip();s.paused=true;s.jobs.AdvanceBehavior(99);Check(s.jobs.Behavior.PreparationRemaining==6,"paused load does not advance");s.paused=false;s.jobs.AdvanceBehavior(6);Check(s.jobs.trip.State==TripState.OnTrip,"load completes actual board once");Stop(s.jobs.current.drop);Check(s.jobs.Interact()&&s.jobs.trip.ArrivalLocked&&s.jobs.Active,"arrival locks before unload");int pay=s.jobs.RequestReward.Total;RoundTrip();s.jobs.trip.Tick(999);s.jobs.AdvanceBehavior(10);Check(!s.jobs.Active&&s.business.passengers[0].paid==pay,"unload cannot change first arrival fare");
  foreach(int choice in new[]{0,1,2}){Fresh();Begin(PassengerType.MuddyLuggage);Answer(choice);if(choice==0)s.jobs.AdvanceBehavior(10);else s.jobs.Interact();Check(s.jobs.trip.State==TripState.OnTrip,"mud option boards");Deliver();Check(s.jobs.Cleanliness==(choice==1?93:98),"mud dirt only unprotected exit plus normal exit");}
  foreach(int choice in new[]{-1,0,1,2}){Fresh();Begin(PassengerType.Food);if(choice>=0)Answer(choice);if(choice==2){s.jobs.AdvanceBehavior(5);RoundTrip();s.jobs.AdvanceBehavior(5);}s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();int expected=choice==1?(s.jobs.Behavior.SpillPlanned?92:98):100;Check(s.jobs.Cleanliness==expected,"food actual consumption choice "+choice);RoundTrip();s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==expected,"food reload replay safe "+choice);Deliver();Check(s.jobs.Cleanliness==expected-2,"ordinary exit remains separate "+choice);}
  Fresh();Begin(PassengerType.Food);Answer(1);s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();string priorEffect=s.jobs.Behavior.DirtEvents[0].Id;Deliver();s.business.ledger.Care.Wash();s.jobs.PrepareForNextCall();Begin(PassengerType.Food);Answer(1);s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();Check(s.jobs.Behavior.DirtEvents[0].Id!=priorEffect&&s.jobs.Behavior.EffectTripIdentity==s.law.tripId&&s.jobs.Cleanliness==(s.jobs.Behavior.SpillPlanned?92:98),"same candidate on a second actual trip soils after wash");
  Fresh();Begin(PassengerType.Sleeping);s.jobs.Behavior.Advance(40,false,true,.4f,100);Check(s.jobs.BehaviorAsleep,"actual non-drunk sleep");Stop(s.jobs.current.drop);Check(s.jobs.Interact()&&s.jobs.trip.ArrivalLocked&&s.jobs.DrunkRide.Waiting&&!s.jobs.DrunkRide.IsDrunk,"non-drunk first arrival wakes through common policy");pay=s.jobs.RequestReward.Total;RoundTrip();s.jobs.DrunkRide.Advance(30,1);s.jobs.trip.Tick(500);Check(s.jobs.Interact()&&!s.jobs.Active&&s.business.passengers[0].paid==pay,"sleep wait does not change fare");
  foreach(PassengerType type in Enum.GetValues(typeof(PassengerType))){if(type==PassengerType.Luggage||type==PassengerType.MuddyLuggage||type==PassengerType.Food||type==PassengerType.Sleeping)continue;Fresh();Begin(type);RoundTrip();Deliver();}
 }
 void SaveReloadCase(){Fresh();Begin(PassengerType.Food);Answer(1);s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();s.business.SaveCheckpoint();Check(File.Exists(s.business.SavePath)&&s.business.SavePath.Contains("artifacts"),"isolated on-disk checkpoint");}
 string RestoreDiagnostic(){var loaded=(CampaignCheckpoint)typeof(BusinessProgress).GetField("loaded",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(s.business);return "path="+s.business.SavePath+" exists="+File.Exists(s.business.SavePath)+" loaded="+(loaded!=null)+" live="+(loaded!=null&&loaded.live!=null)+" restoring="+typeof(BusinessProgress).GetField("restoring",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(s.business)+" state="+s.jobs.trip.State+" type="+(s.jobs.Behavior==null?"null":s.jobs.Behavior.Type.ToString())+" status="+s.business.saveStatus;}
 void ReloadChecks(){report.AppendLine("RESTORE "+RestoreDiagnostic());s.paused=false;s.business.preparing=false;Time.timeScale=1;Check(s.jobs.trip.State==TripState.OnTrip&&s.jobs.Behavior!=null&&s.jobs.Behavior.Type==PassengerType.Food&&s.jobs.Behavior.ConsumptionOccurred,"new process resumes consumed food passenger");int clean=s.jobs.Cleanliness;s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==clean,"new process dirt exactly once");Deliver();Check(s.jobs.Cleanliness==clean-2,"new process normal exit once");s.business.SaveCheckpoint();}
 IEnumerator Capture(string name){yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/passenger-behavior-"+name+".png"));yield return new WaitForSecondsRealtime(.5f);}
 bool Guard(Action action){try{action();return true;}catch(Exception e){report.AppendLine(e.ToString());Debug.LogException(e);return false;}}
 IEnumerator Start(){
  yield return new WaitForSecondsRealtime(2);s=FindObjectOfType<DriveSession>();while(s&&!s.StartupReady)yield return null;if(s)report.AppendLine("PRE_BOUNDARY "+RestoreDiagnostic());yield return null;yield return null;yield return null;
  // Business.Start restores its live snapshot in a separate next-frame coroutine. Never disable it before that boundary.
  var restoringField=typeof(BusinessProgress).GetField("restoring",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);float restoreDeadline=Time.realtimeSinceStartup+10;while(s&&(bool)restoringField.GetValue(s.business)&&Time.realtimeSinceStartup<restoreDeadline)yield return null;
  reload=Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerBehaviorReloadTest")>=0;
  bool ok=Guard(()=>{Check(s!=null,"session initialized");Check(!(bool)restoringField.GetValue(s.business),"startup restore completed within10seconds");FreezeSystems();if(reload)ReloadChecks();else MainChecks();});
  if(ok&&!reload){
   ok=Guard(()=>{Fresh();Begin(PassengerType.Food);s.requests.BeginKind(RequestKind.LocalChat);typeof(PassengerRequestUI).GetField("legacy",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(s.requests,false);});
   yield return null;
   if(ok)ok=Guard(()=>{s.requests.AdvanceSafeStop(2.1f);Check(s.requests.Choose(PassengerReply.Alternative),"real frame prior I response");Check(!s.jobs.RespondBehavior(1)&&s.jobs.Behavior.Choice==-1,"real frame I does not authorize food");});
   yield return null;
   if(ok)ok=Guard(()=>Check(s.jobs.RespondBehavior(0),"actual next frame permits deliberate food choice"));
  }
  if(ok&&!reload&&Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerBehaviorCapture")>=0){
   ok=Guard(()=>{Fresh();Begin(PassengerType.Luggage);});if(ok)yield return Capture("preparation");
   if(ok)ok=Guard(()=>{Answer(0);s.jobs.AdvanceBehavior(10);Deliver();s.GetComponent<RideCompletionPanel>().ShowLast();});if(ok)yield return Capture("receipt");
   if(ok)ok=Guard(()=>{Fresh();Begin(PassengerType.Food);});if(ok)yield return Capture("food-choice");
   if(ok)ok=Guard(()=>{Fresh();Begin(PassengerType.Sleeping);s.jobs.Behavior.Advance(40,false,true,.4f,100);s.requests.SuspendUnansweredForSleep();s.GetComponent<PassengerBehaviorUI>().NotifyStateChanged();});if(ok)yield return Capture("sleeping");
  }
  if(ok&&!reload)ok=Guard(SaveReloadCase);
  Directory.CreateDirectory("artifacts");File.WriteAllText("artifacts/passenger-behavior-"+(reload?"reload":"player")+".txt",(ok?"PASS":"FAIL")+" checks="+checks+"\n"+report);Debug.Log("PASSENGER_BEHAVIOR_PLAYER_"+(ok?"OK":"FAILED")+" checks="+checks);Application.Quit(ok?0:1);
 }
}
